  "stuSess.refundContactNote": "Pentru rambursare, contactează <a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a>.",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">Ai întrebări sau probleme? Contactează <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a>.</p><p class=\"font-semibold text-emerald-900\">Rambursarea ta a fost inițiată prin Stripe.</p><p class=\"text-emerald-800 mt-1\">Rambursările pe card ajung de obicei în aproximativ <strong>5–10 zile lucrătoare</strong> (termenul poate varia în funcție de bancă). Dacă suma nu ajunge în intervalul obișnuit, scrie la <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a>.</p>",
  "stuSess.refundSuccessManualTutor": "<p>Se pare că această lecție nu a fost achitată prin Stripe în Tutlio (de exemplu, plata s-a făcut prin transfer bancar sau numerar). Rambursarea automată nu este disponibilă aici.</p><p class=\"mt-2\">Pentru a stabili rambursarea, contactează profesorul <strong>{tutor}</strong> — folosește adresa de e-mail sau datele din rezervări ori primite direct de la profesor.</p>",
  "stuSess.refundSuccessManualOrg": "<p>Se pare că această lecție nu a fost achitată prin Stripe în Tutlio (de exemplu, plata s-a făcut prin transfer bancar sau numerar). Rambursarea automată nu este disponibilă aici.</p><p class=\"mt-2\">Deoarece urmezi lecții printr-o organizație, contactează <strong>administratorul organizației</strong> (prin profesor sau folosind datele publice de contact ale organizației).</p>",
  "stuSess.refundTutorFallback": "profesorul tău",
