  "landing.footerResources": "Resurse",
  "landing.footerCompany": "Centru",
  "landing.faq.whatIsQ": "Ce este Tutlio?",
  "landing.faq.whatIsA": "Tutlio este o platformă de gestionare a meditațiilor care ajută profesorii particulari și școlile de meditații să gestioneze programările, plățile, comunicarea cu elevii și evidența lecțiilor într-un singur loc.",
  "landing.faq.whoForQ": "Cui se adresează Tutlio?",
  "landing.faq.whoForA": "Tutlio este conceput pentru profesori particulari, profesori de muzică, limbi străine și matematică, școli de meditații și centre educaționale de orice dimensiune.",
  "landing.faq.waitlistQ": "Cum funcționează lista de așteptare pentru elevi?",
  "landing.faq.waitlistA": "Când un elev anulează o lecție, intervalul eliberat este oferit automat elevilor de pe lista de așteptare. Primul care confirmă primește locul - astfel, profesorii nu pierd venituri din anulări.",
  "landing.faq.freeTrialQ": "Există o perioadă de probă gratuită?",
  "landing.faq.freeTrialA": "Da! Fiecare cont nou primește automat 7 zile gratuite - fără cod. Nu ești taxat în perioada de probă și poți anula oricând.",
  "landing.faq.languagesQ": "Ce limbi acceptă Tutlio?",
  "landing.faq.languagesA": "Tutlio este disponibil în {count} limbi: {languages}.",
  "landing.faqTitle": "Întrebări frecvente",
  "landing.feature.digital-business-card": "Carte de vizită digitală",
  "landing.feature.digital-business-cardDesc": "Distribuie o pagină profesională unde elevii pot afla mai multe despre tine, pot vedea prețurile și disponibilitatea actualizate și pot solicita imediat o lecție.",

  // featuresIndex
  "featuresIndex.newBadge": "Nou",

  // feature
  "feature.digital-business-card.pageTitle": "O carte de vizită digitală care transformă interesul în cereri de lecții",
  "feature.digital-business-card.pageDesc": "Oferă fiecărui elev potențial un link bine prezentat, cu povestea ta, lecțiile, prețurile, recenziile și disponibilitatea actualizată. Elevii aleg imediat lecția și ora - iar cererile nu se mai pierd în conversații lungi.",
  "feature.digital-business-card.detailsTitle": "Tot ce îi trebuie unui elev potențial pentru a spune da",
  "feature.digital-business-card.oneLink": "Un singur link pentru întreaga ta activitate de meditații",
  "feature.digital-business-card.oneLinkDesc": "Înlocuiește profilurile sociale disparate, listele de prețuri și mesajele pentru rezervări cu o singură pagină pe care o poți distribui oriunde.",
  "feature.digital-business-card.liveAvailability": "Disponibilitate mereu actualizată",
  "feature.digital-business-card.liveAvailabilityDesc": "Intervalele libere vin direct din calendarul Tutlio, astfel încât clienții solicită doar orele la care dorești să predai.",
  "feature.digital-business-card.instantEnquiries": "Cereri de lecții în timp ce predai",
  "feature.digital-business-card.instantEnquiriesDesc": "Un părinte sau un elev alege lecția, formatul și ora, apoi își lasă datele. Cererea completă ajunge la tine fără o conversație pentru stabilirea programului.",
  "feature.digital-business-card.professionalBrand": "O primă impresie profesională",
  "feature.digital-business-card.professionalBrandDesc": "Prezintă fotografia, metoda de predare, materiile, prețurile, recenziile verificate și culorile brandului pe o pagină care funcționează foarte bine pe orice telefon.",
  "feature.digital-business-card.faq.whatShowsQ": "Ce pot afișa pe cartea mea de vizită digitală?",
  "feature.digital-business-card.faq.whatShowsA": "Poți prezenta o introducere, materiile, formatele lecțiilor, prețurile publice, intervalele disponibile din calendar, locația, limbile, linkurile sociale și recenziile verificate ale elevilor.",
  "feature.digital-business-card.faq.howBookingWorksQ": "Clientul rezervă imediat o lecție confirmată?",
  "feature.digital-business-card.faq.howBookingWorksA": "Clientul alege o lecție și un interval disponibil, apoi trimite o cerere completă de rezervare. O primești în Tutlio și poți confirma noul elev înainte ca lecția să fie adăugată în program.",
  "feature.digital-business-card.faq.whereShareQ": "Unde ar trebui să distribui pagina?",
  "feature.digital-business-card.faq.whereShareA": "Folosește linkul pe Instagram, TikTok, în grupuri Facebook, reclame, semnături de e-mail, mesaje și coduri QR. Același link rămâne actualizat chiar dacă prețurile sau calendarul se schimbă.",
  "feature.digital-business-card.demo.eyebrow": "Previzualizare interactivă pentru client",
  "feature.digital-business-card.demo.title": "Încearcă procesul de rezervare",
  "feature.digital-business-card.demo.desc": "Alege o lecție și o oră mai jos. Acesta este parcursul simplu pe care îl urmează un client nou de la linkul distribuit de tine.",
  "feature.digital-business-card.demo.profile": "Profesor de matematică · clasele 9–12",
  "feature.digital-business-card.demo.available": "Acceptă elevi noi",
  "feature.digital-business-card.demo.pickLesson": "1. Alege o lecție",
  "feature.digital-business-card.demo.individual": "Lecție individuală",
  "feature.digital-business-card.demo.individualDesc": "60 min · plan personal de învățare",
