  "feature.digital-business-card.demo.trial": "Discuție introductivă",
  "feature.digital-business-card.demo.trialDesc": "20 min · să ne cunoaștem",
  "feature.digital-business-card.demo.pickTime": "2. Alege un interval disponibil",
  "feature.digital-business-card.demo.tomorrow": "Mâine",
  "feature.digital-business-card.demo.thursday": "Joi",
  "feature.digital-business-card.demo.online": "Online",
  "feature.digital-business-card.demo.summary": "Cererea ta de lecție",
