  "feature.digital-business-card.demo.format": "Format",
  "feature.digital-business-card.demo.cta": "Solicită această lecție",
  "feature.digital-business-card.demo.successTitle": "Cererea de lecție este pregătită",
  "feature.digital-business-card.demo.successDesc": "Acesta este întregul parcurs al clientului. Pe o carte de vizită publicată, datele și ora aleasă ajung la tine în Tutlio și prin e-mail.",
  "feature.digital-business-card.demo.tryAgain": "Încearcă altă oră",
