  // orgTutorPolicy
  "orgTutorPolicy.title": "Regulament intern pentru profesori",
  "orgTutorPolicy.intro": "Consultă regulamentul intern al organizației înainte de a folosi platforma.",
  "orgTutorPolicy.acceptBtn": "Am înțeles",
  "orgTutorPolicy.viewBtn": "Vezi regulamentul intern",
  "orgTutorPolicy.s1Title": "1. Dispoziții generale",
  "orgTutorPolicy.s1Body": "Acest regulament reglementează utilizarea platformei Tutlio („Platforma”) de către tine în calitate de cadru didactic sau profesor particular („Profesorul”). Ai fost invitat să folosești Platforma de agenția educațională, școala sau centrul de meditații pe care îl reprezinți („Organizația”). Întreținerea și asistența tehnică ale Platformei sunt asigurate de MB Tutlio. Prin utilizarea contului, accepți acest Regulament și Politica de confidențialitate.",
  "orgTutorPolicy.s2Title": "2. Gestionarea contului și a programelor",
  "orgTutorPolicy.s2Intro": "Platforma este concepută astfel încât să nu mai fie nevoie să petreci timp stabilind orele lecțiilor cu elevii.",
  "orgTutorPolicy.s2Link": "Link unic: primești un link personal de rezervare a lecțiilor (în funcție de materiile pe care le predai), pe care elevii îl folosesc pentru a programa lecții.",
  "orgTutorPolicy.s2Calendar": "Sincronizarea calendarului: disponibilitatea ta depinde direct de integrarea Google Calendar (sincronizare în 2 direcții). Ai responsabilitatea personală de a te asigura că intervalele libere afișate în calendar sunt corecte și actualizate. Platforma nu va permite elevilor să rezerve intervalele marcate ca ocupate în calendarul tău.",
  "orgTutorPolicy.s2Security": "Securitatea contului: contul tău este personal. Trebuie să păstrezi datele de autentificare în siguranță și să nu le comunici terților.",
  "orgTutorPolicy.s3Title": "3. Anularea lecțiilor și lista de așteptare",
  "orgTutorPolicy.s3Intro": "Platforma te ajută să valorifici la maximum programul și să eviți intervalele neocupate:",
  "orgTutorPolicy.s3Auto": "Dacă un elev anulează o lecție, Platforma trimite automat o notificare (SMS/e-mail) celorlalți elevi de pe lista ta de așteptare, oferindu-le intervalul eliberat. Nu este necesară nicio acțiune suplimentară din partea ta.",
  "orgTutorPolicy.s3Rules": "Regulile de anulare a lecțiilor (cu cât timp înainte poate fi anulată o lecție și consecințele) sunt stabilite de Organizația ta.",
  "orgTutorPolicy.s4Title": "4. Finanțe și plăți",
  "orgTutorPolicy.s4Intro": "Nu trebuie să te ocupi de facturare sau de colectarea plăților de la părinți:",
  "orgTutorPolicy.s4Advance": "Toate plățile elevilor (sau ale părinților) pentru lecțiile tale sunt colectate în avans prin Platformă și transferate direct Organizației tale.",
  "orgTutorPolicy.s4Confirmed": "Ții o lecție numai când aceasta este confirmată în sistem (ceea ce înseamnă că a fost deja încasată plata).",
  "orgTutorPolicy.s4Contact": "Pentru remunerație, programul viramentelor și alte aspecte financiare, contactează direct administratorul Organizației tale. MB Tutlio nu efectuează tranzacții financiare directe cu Profesorii.",
  "orgTutorPolicy.s5Title": "5. Protecția datelor elevilor (GDPR)",
  "orgTutorPolicy.s5Intro": "În calitate de Profesor, ai acces la datele personale ale elevilor, notele interne și materialele de învățare. Te angajezi:",
  "orgTutorPolicy.s5Use": "Să folosești aceste date exclusiv pentru organizarea și desfășurarea lecțiilor.",
  "orgTutorPolicy.s5NoCopy": "Să nu copiezi, exporți sau distribui datele de contact ale elevilor sau părinților în afara Platformei.",
  "orgTutorPolicy.s5Notes": "Să protejezi înregistrările interne ale Organizației (note despre progresul elevilor), vizibile doar pentru tine și administrația Organizației, nu pentru elevi sau părinți.",
  "orgTutorPolicy.s5Termination": "La încetarea relației de colaborare cu Organizația, accesul tău la aceste date va fi revocat imediat.",
  "orgTutorPolicy.s6Title": "6. Funcționarea tehnică și limitarea răspunderii",
  "orgTutorPolicy.s6Body": "Utilizarea Platformei în scopuri ilegale, distribuirea de linkuri rău intenționate în materialele de lecție sau perturbarea sistemului în alt mod sunt interzise. MB Tutlio asigură funcționarea și întreținerea tehnică a Platformei, dar nu își asumă răspunderea pentru întreruperi cauzate de conexiunea ta la internet, defectarea dispozitivelor sau configurarea incorectă a setărilor Google Calendar.",
  "orgTutorPolicy.s7Title": "7. Asistență și contacte",
  "orgTutorPolicy.s7Org": "Pentru întrebări despre programul lecțiilor, remunerații, atribuirea elevilor sau organizarea activității, contactează administratorul Organizației tale.",
  "orgTutorPolicy.s7Tech": "Pentru erori tehnice ale Platformei (sincronizarea calendarului nu funcționează, nu primești notificări), informează administratorul Organizației tale, care va contacta echipa de asistență tehnică Tutlio.",

