  "quiz.info.story.company.brandAlt": "Sigla PRO KLASĖ",
  "quiz.info.story.company.customerName": "PRO KLASĖ",
  "quiz.info.story.company.customerType": "Echipa unei organizații de meditații",
  "quiz.info.story.company.story": "„Înainte de Tutlio, modificările lecțiilor, comentariile și orele profesorilor erau împrăștiate prin mesaje. Acum întreaga echipă lucrează cu același program și nu mai trebuie să cerem actualizări la sfârșitul lunii.”",
  "quiz.info.story.company.proof1": "Programarea echipei",
  "quiz.info.story.company.proof2": "Reguli personalizate de remunerare",
  "quiz.info.story.company.proof3": "Monitorizarea lecțiilor",
  "quiz.info.story.company.detail": "„Cea mai mare diferență a fost adaptarea aprobărilor, lecțiilor de recuperare și regulilor de remunerare la modul în care echipa noastră lucrează deja, în loc să fim obligați să folosim un proces generic.”",
  "quiz.info.story.school.eyebrow": "De la un client Tutlio",
