  "quiz.info.story.school.disclosure": "Modul de lucru al clientului",
  "quiz.info.story.school.brandAlt": "Sigla VšĮ „Laisvi vaikai”",
  "quiz.info.story.school.customerName": "VšĮ „Laisvi vaikai”",
  "quiz.info.story.school.customerType": "Echipa de administrare a școlii",
  "quiz.info.story.school.story": "„Ne doream un singur loc în care echipa să poată urmări o familie de la înscriere și contract până la fiecare rată. Tutlio ne oferă această continuitate fără să întreținem foi de calcul paralele.”",
  "quiz.info.story.school.proof1": "Contracte și semnături",
  "quiz.info.story.school.proof2": "Grafice de rate",
  "quiz.info.story.school.proof3": "Exporturi pentru contabilitate",
  "quiz.info.story.school.detail": "„Cea mai clară îmbunătățire este că vedem starea contractului, semnăturii și plății fără să întrebăm mai multe persoane sau să verificăm fișiere separate.”",
  "quiz.businessCard.eyebrow": "Pagina ta integrată pentru dezvoltarea afacerii",
