  "quiz.info.assurance.solo.eyebrow": "Conceput pentru un început practic",
  "quiz.info.assurance.solo.title": "Nu trebuie să îți reorganizezi întreaga afacere din prima zi",
  "quiz.info.assurance.solo.body": "Un sistem util ar trebui să reducă rapid presiunea și să se extindă doar când ai nevoie de mai mult.",
  "quiz.info.assurance.solo.point1": "Începe cu calendarul și elevii, apoi adaugă finanțele și automatizarea în ritmul tău.",
