  "quiz.info.assurance.solo.point3": "Oferă elevilor un proces profesional fără să adaugi o altă sarcină manuală.",
  "quiz.info.assurance.company.eyebrow": "Control pentru o echipă în creștere",
  "quiz.info.assurance.company.title": "O imagine comună nu trebuie să însemne acces comun la toate datele",
  "quiz.info.assurance.company.body": "Tutlio este conceput pentru ca administratorii și profesorii să lucreze în același sistem, cu acces potrivit rolului fiecăruia.",
  "quiz.info.assurance.company.point1": "Separă monitorizarea administrativă de spațiul de lucru zilnic al profesorului.",
  "quiz.info.assurance.company.point2": "Centralizează datele operaționale fără a obliga toate rolurile să urmeze același proces.",
