  "quiz.info.assurance.school.eyebrow": "Siguranță pentru operațiunile sensibile",
  "quiz.info.assurance.school.title": "Evidențele școlii au nevoie de claritate, control al accesului și un istoric de încredere",
  "quiz.info.assurance.school.body": "Fluxul Tutlio pentru școli este construit în jurul relației administrative reale dintre personal, elevi, părinți, contracte și plăți.",
  "quiz.info.assurance.school.point1": "Păstrează datele organizației în fluxuri administrative școlare cu acces adaptat rolurilor.",
