  "quiz.offer.testimonial.solo.name3": "Ieva",
  "quiz.offer.testimonial.solo.role3": "Profesor de chimie și biologie",
  "quiz.offer.testimonial.solo.copy3": "„O pagină publică și rezervarea într-un singur link îi ajută pe elevii noi să decidă mai repede, iar eu nu mai trebuie să trimit fiecăruia aceleași informații separat.”",
  "quiz.offer.testimonial.solo.name4": "Lukas",
  "quiz.offer.testimonial.solo.role4": "Profesor de fizică",
  "quiz.offer.testimonial.solo.copy4": "„Văd imediat în calendar lecțiile, modificările și starea plăților. Administrarea zilnică a devenit mult mai scurtă și mai clară.”",
  "quiz.offer.testimonial.company.name1": "PRO KLASĖ",
  "quiz.offer.testimonial.company.role1": "Echipa unei organizații de meditații",
  "quiz.offer.testimonial.company.copy1": "„Modificările lecțiilor, comentariile profesorilor și orele ajungeau înainte prin mesaje separate. Acum echipa de administrare poate vedea imaginea completă într-un singur program.”",
  "quiz.offer.testimonial.company.name2": "Centru independent de meditații",
  "quiz.offer.testimonial.company.role2": "Proprietar · 8 profesori",
  "quiz.offer.testimonial.company.copy2": "„Petreceam serile de vineri comparând calendarul cu mesajele profesorilor înainte de a pregăti remunerațiile. Cu Tutlio, mare parte din verificare este deja făcută.”",
  "quiz.offer.testimonial.company.name3": "Studio de meditații la limbi străine",
  "quiz.offer.testimonial.company.role3": "Coordonator operațional · 14 profesori",
  "quiz.offer.testimonial.company.copy3": "„Când o lecție este mutată, echipa vede imediat aceeași actualizare. Avem mai puține mesaje de clarificare, iar părinții primesc răspunsuri mult mai clare.”",
  "quiz.offer.testimonial.company.name4": "Academie de pregătire pentru examene",
  "quiz.offer.testimonial.company.role4": "Coordonator financiar · 22 de profesori",
  "quiz.offer.testimonial.company.copy4": "„Regulile noastre de remunerare diferă în funcție de tipul lecției, așa că sfârșitul lunii presupunea multe verificări manuale. Fluxul Tutlio a făcut acest proces mult mai liniștit.”",
  "quiz.offer.testimonial.school.name1": "VšĮ „Laisvi vaikai”",
  "quiz.offer.testimonial.school.role1": "Echipa de administrare a școlii",
  "quiz.offer.testimonial.school.copy1": "„Cea mai clară îmbunătățire este că vedem starea contractului, semnăturii și plății fără să întrebăm mai multe persoane sau să verificăm fișiere separate.”",
  "quiz.offer.testimonial.school.name2": "Școală comunitară independentă",
  "quiz.offer.testimonial.school.role2": "Coordonator de înscrieri · 86 de cursanți",
  "quiz.offer.testimonial.school.copy2": "„Perioada înscrierilor însemna urmărirea formularelor, datelor părinților și contractelor semnate în dosare separate. Acum echipa noastră poate urmări fiecare familie dintr-un singur loc.”",
  "quiz.offer.testimonial.school.name3": "Centru de învățare după școală",
  "quiz.offer.testimonial.school.role3": "Administrator · 120 de cursanți",
  "quiz.offer.testimonial.school.copy3": "„Graficele de rate au simplificat mult urmărirea plăților. Văd ce este scadent înainte să contactez un părinte, fără să refac lista manual.”",
  "quiz.offer.testimonial.school.name4": "Școală de educație artistică",
  "quiz.offer.testimonial.school.role4": "Coordonator financiar · 9 programe",
  "quiz.offer.testimonial.school.copy4": "„Exportul contabil folosește acum aceleași evidențe ca documentele contractuale și plățile, așa că sfârșitul lunii implică mult mai puține corecții.”",
  "quiz.offer.savings.eyebrow": "Impact estimat asupra timpului",
  "quiz.offer.savings.subtitle": "Reducerea estimată a administrării repetitive când aceste procese sunt conectate prin Tutlio.",
  "quiz.offer.savings.totalLabel": "reducere potențială a administrării recurente",
