  "schoolsLanding.ctaBannerBtn": "Contactează-ne",
  "schoolsLanding.faq.whatIsQ": "Ce este Tutlio pentru școli?",
  "schoolsLanding.faq.whatIsA": "Tutlio Schools este un software de administrare pentru școli de meditații - orarul profesorilor, CRM pentru elevi, contracte, plăți și rapoarte într-o singură platformă.",
  "schoolsLanding.faq.whoForQ": "Cui i se adresează Tutlio Schools?",
  "schoolsLanding.faq.whoForA": "Școli de limbi străine, centre de meditații, școli de muzică, programe de pregătire pentru examene și orice organizație care coordonează mai mulți profesori și elevi.",
  "schoolsLanding.faq.contractsQ": "Putem gestiona contracte și plăți?",
  "schoolsLanding.faq.contractsA": "Da. Platforma acceptă șabloane de contract, semnare electronică, plata în rate, plăți prin Stripe și raportare financiară.",
  "schoolsLanding.faq.pricingQ": "Cum funcționează prețurile pentru școli?",
  "schoolsLanding.faq.pricingA": "Școlile primesc prețuri personalizate, în funcție de numărul de profesori și de nevoi. Contactează-ne pentru o ofertă adaptată.",
  "schoolsLanding.faq.trialQ": "Putem încerca înainte de a cumpăra?",
  "schoolsLanding.faq.trialA": "Da - programează o consultanță și o demonstrație gratuite. Îți arătăm cum se potrivește Tutlio cu modul de lucru al școlii tale.",
