  "landing.custom.badge": "Marea diferență",
  "landing.custom.title": "Un software care se adaptează la felul în care lucrezi - nu invers",
  "landing.custom.sub": "Fiecare școală și fiecare agenție lucrează puțin altfel. Când fluxul standard nu se potrivește, adaptăm Tutlio la procesul tău - de obicei în câteva săptămâni, nu în trimestre. Câteva lucruri pe care le-am construit deja pentru clienți:",
  "landing.custom.ex1Title": "Contracte anuale cu semnătură electronică",
  "landing.custom.ex1Desc": "O școală privată avea nevoie ca părinții să semneze electronic contractele anuale, să plătească în rate și ca fiecare plată să apară într-un export gata pentru contabilitate. Acum tot ciclul se desfășoară în Tutlio.",
  "landing.custom.ex2Title": "Reguli de plată și comision pentru profesori",
  "landing.custom.ex2Desc": "O agenție plătește fiecare profesor în funcție de materie și de tipul lecției, adăugând un comision al firmei. Le-am modelat regulile, așa că situațiile lunare ale profesorilor și facturile se generează automat.",
  "landing.custom.ex3Title": "Oferte pentru părinți dintr-un singur clic",
  "landing.custom.ex3Desc": "O școală voia să propună lecții suplimentare prin e-mail și să lase părinții să le accepte dintr-un singur clic - fără cont și fără tipărire. Acceptarea, facturarea și invitația la prima lecție se derulează acum de la sine.",
  "landing.custom.ex4Title": "Brandul tău, pe site-ul tău",
  "landing.custom.ex4Desc": "O organizație și-a dorit propriul logo și propriile culori, plus o autentificare integrată în site, astfel încât elevii și părinții să nu simtă niciodată că l-au părăsit. Acum Tutlio funcționează sub brandul lor.",
  "landing.custom.note": "Nimic din toate acestea nu este o ediție specială. Fiecare adaptare devine parte din același produs pe care echipa ta îl folosește deja, cu toate actualizările viitoare incluse.",
  "landing.custom.cta": "Spune-ne cum lucrezi",
  "landing.custom.soloTitle": "Îți lipsește ceva?",
  "landing.custom.soloNote": "Construim în mod constant funcții pentru clienți individuali - de la o regulă de plată până la un flux de lucru întreg. Spune-ne ce ți-ar economisi timp.",
  "stats.cancellationPartTutor": "profesor: {count}",
